  const dueDate = new Date($json.due_date).toLocaleDateString('nl-NL', { day: '2-digit', month: '2-digit', year: 'numeric' });
  const payLine = $json.payment_url ? `

Direct online betalen (o.a. met iDEAL): ${$json.payment_url}` : '';
  if ($json.next_reminder_number === 3) {
    return `Beste ${$json.client_name},

