${$json.company_name}`;
})() }}

parameters.jsCode:
const raw = $json.client_phone || '';
let digits = raw.replace(/[^0-9]/g, '');
if (digits.startsWith('0')) {
  digits = '31' + digits.slice(1);
}

const payLine = $json.payment_url ? ` Betaal direct: ${$json.payment_url}` : '';
const text = $json.next_reminder_number === 3
  ? `Beste ${$json.client_name}, dit is onze laatste herinnering voor factuur ${$json.invoice_number} (${$json.days_overdue} dagen te laat). Bij uitblijven van betaling binnen 7 dagen kunnen incassomaatregelen volgen.${payLine} Al betaald? Dan kunt u dit negeren. - ${$json.company_name}`
  : `Beste ${$json.client_name}, factuur ${$json.invoice_number} staat nog open (${$json.days_overdue} dagen na de vervaldatum). Wilt u deze op korte termijn voldoen?${payLine} - ${$json.company_name}`;

return [{ json: { number: digits, text: text } }];
